(316, 13, 'customer', 'PORT=5005\nFRONTEND_PORT=5173\n\nVITE_APP_NAME=Elevan Property\nAPP_NAME=Elevan Property\n\nDB_HOST=localhost\nDB_USER=root\nDB_PASSWORD=\nDB_NAME=db_property\nDB_DIALECT=mysql\n\nGOOGLE_SHEET_ID=1nwy276VXH0JvDZVOoddBbqmr9jwpydoKrukWY2Jukw4\nGOOGLE_SHEET_GID=0\nGOOGLE_SHEET_TAB_NAME=\nGOOGLE_SERVICE_ACCOUNT_JSON_PATH=./google-service-account.json\n\nOPENAI_API_KEY=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\n# OPENAI_MODEL=gpt-5.4-mini\nOPENAI_MODEL=gpt-4o-mini\nOPENAI_STORE_RESPONSE=true\nOPENAI_MAX_OUTPUT_TOKENS=0\n\nAI_PRIMARY_PROVIDER=chatgpt\nENABLE_CLAUDE_FALLBACK=true\nENABLE_CHATBOT_PRIVATE_CONTROLLER=true\n\nANTHROPIC_API_KEY=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\nCLAUDE_MODEL=claude-haiku-4-5\nCLAUDE_API_VERSION=2023-06-01\nCLAUDE_MAX_TOKENS=200\n\nFONNTE_TOKEN=m5HDmV4hAYRFBgTdkfDR\nENABLE_AI_WHATSAPP=true\n\n# Fonnte Message Polling (aktif polling ke Fonnte API untuk ambil pesan masuk)\n# Set false untuk matikan polling\nFONNTE_POLLING_ENABLED=true\n# Interval polling dalam milidetik (default: 10000 = 10 detik)\nFONNTE_POLLING_INTERVAL_MS=10000\n\n# ==============================================================\n# MASSEGE_TERMINAL — Platform mana yang tampil di terminal\n# ==============================================================\n# Nilai: FONNTE | DIALOG | WATI (satu atau lebih, pisah koma)\n# FONNTE = fonnteChatController menampilkan chat di terminal\n# DIALOG = dialogChatController menampilkan chat di terminal\n# WATI   = watiChatController menampilkan chat di terminal\n#\n# Contoh satu platform  : MASSEGE_TERMINAL=FONNTE\n# Contoh multi platform : MASSEGE_TERMINAL=FONNTE,DIALOG\n# Semua platform        : MASSEGE_TERMINAL=FONNTE,DIALOG,WATI\nMASSEGE_TERMINAL=FONNTE\n\nCHATBOT_COOKIE_TTL_MINUTES=90\n\nSKILL_MAX_WEBSITE_CHARACTERS=12000\nSKILL_MAX_RESPONSE_CHARACTERS=22000\nSKILL_MAX_PROJECT_CHARACTERS=36000\n\n# Apify - Rumah123 Scraper\nAPIFY_API_TOKEN=apify_api_hd8TzxQYbulU71ol5QfIVMeJsDdXX21md2H0\n\n# ON/OFF toggle untuk live Rumah123 data\n# ON  = Chatbot menggunakan live data dari Rumah123 (via Apify)\n# OFF = Chatbot menggunakan static data dari JSON catalog (frontend/public/json_data)\nRUMAH123_DATA=OFF\n\n# Lokasi yang di-warmup saat server start (pisahkan dengan koma)\nRUMAH123_WARMUP_LOCATIONS=Jakarta Selatan,Surabaya,Bandung,Bali\n\n# ==============================================================\n# 360DIALOG WHATSAPP API\n# ==============================================================\n\n# Mode: true = sandbox (testing), false = production\nDIALOG360_SANDBOX=true\n\n# Webhook base URL — otomatis dipakai saat /setup-webhook dipanggil\n# Update setiap kali ngrok URL berubah\nDIALOG360_WEBHOOK_BASE_URL=https://spotter-dragging-sporting.ngrok-free.dev\n\n# CARA SETUP SANDBOX:\n#   1. Kirim \"START\" ke +551146733492 via WhatsApp → dapat API key\n#   2. Simpan API key ke DB per agent:\n#      UPDATE users SET dialog360_token=\'[API_KEY]\' WHERE name=\'[AGENT]\';\n#   3. Daftarkan webhook:\n#      POST http://localhost:5005/api/dialog-chat/setup-webhook\n#      Body: { \"agentId\": \"[user_id]\" }\n#   4. Kirim pesan ke nomor sandbox → cek terminal\n\nWATI_API_TOKEN=wati_2688d36b-1f09-41b6-b09d-1872e6ce6c8e.699lefCaexEWDQDc076Wb9FeddD7VddVcuVMw018Kio4nla5fp1VnNPkMO6jJBhk3Bb0GGzw-I3X36nHOoQHh4X_3JK2ps8t9hLSXds5Skgrc-XFfJ_2FSXRlmUMJC94\n\n# WATI API URL - Extract dari WATI Dashboard URL yang Anda screenshot\n# Dari: live.wati.io/10167096/contacts\n# Maka API URL adalah:\nWATI_API_URL=https://live.wati.io/10167096/api/v1\n\n# Jika error 404, coba salah satu alternatif:\n# WATI_API_URL=https://live-mt-server.wati.io/10167096/api/v1\n# WATI_API_URL=https://live.wati.io/api/v1\n\n\n# ==============================================================\n# AUTHENTICATION SETTINGS (Login & Register Users)\n# ==============================================================\n\n# JWT Secrets — ganti dengan string random sebelum production\nACCESS_TOKEN_SECRET=elevan_access_secret_iuewg928g0wbigw78981091nLJkosniqLwq83egijc\nREFRESH_TOKEN_SECRET=elevan_refresh_secret_837qbdgwosDapoznchvdo07sNckaidskjajwiuq98y8\n\n# Expiry token — sesuai jsonwebtoken expiresIn format (60s, 5m, 2h, 1d)\n# Access token expire setiap 5 menit (frontend auto-refresh ke /refreshTokenController)\nACCESS_TOKEN_EXPIRY=5m\nREFRESH_TOKEN_EXPIRY=1d\n\n# Cookie name untuk menyimpan refresh_token (HttpOnly)\nCOOKIE_REFRESH_TOKEN=Elevan_Refresh_Token\n\n# Bcrypt salt rounds (10-12 recommended)\nBCRYPT_SALT_ROUNDS=10\n\n# ==============================================================\n# HTTP STATUS CODES (untuk konsistensi respon controller)\n# ==============================================================\nHTTP_OK=200\nHTTP_CREATED=201\nHTTP_NO_CONTENT=204\nHTTP_BAD_REQUEST=400\nHTTP_UNAUTHORIZED=401\nHTTP_FORBIDDEN=403\nHTTP_NOT_FOUND=404\nHTTP_CONFLICT=409\nHTTP_INTERNAL_SERVER_ERROR=500\nHTTP_NOT_IMPLEMENTED=501\nHTTP_BAD_GATEWAY=502\nHTTP_SERVICE_UNAVAILABLE=503\n------------------------', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"fonnte_1780649520387\",\"platform\":\"fonnte\"}', '2026-06-05 08:52:00', '2026-06-05 08:52:00'),
