INSERT INTO `chat_messages` (`id`, `chatSessionId`, `role`, `message`, `channel`, `metadata`, `createdAt`, `updatedAt`) VALUES
(852, 13, 'ai', 'Oke, jelas! Sekarang Kak mau sewa **apartemen** dengan budget **Rp 1.300.000 - Rp 2.500.000/malam**, dan rencana sewa **seminggu**. \n\nDi kota atau area mana yang Kak inginkan untuk apartemennya? 📍', 'whatsapp', '{\"aiProvider\":\"claude\",\"contextSource\":\"flat_json\"}', '2026-06-18 09:34:13', '2026-06-18 09:34:13'),
(853, 13, 'customer', 'Saya mau sewa apartemen di surabaya, dekat PTC dan cafe.', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"fonnte_1781775292849\",\"platform\":\"fonnte\"}', '2026-06-18 09:34:52', '2026-06-18 09:34:52'),
(854, 13, 'ai', 'Oke, jelas! Lokasi Surabaya sudah saya catat, dekat PTC dan cafe. 😊\n\nSekarang, akan tinggal bersama siapa saja? Biar saya carikan apartemen yang pas jumlah kamarnya 🛏️', 'whatsapp', '{\"aiProvider\":\"claude\",\"contextSource\":\"flat_json\"}', '2026-06-18 09:34:56', '2026-06-18 09:34:56'),
(855, 13, 'customer', 'Saya tinggal sendiri. tolong apartemennya ada kolam renang, gym dan hall', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"fonnte_1781775329896\",\"platform\":\"fonnte\"}', '2026-06-18 09:35:29', '2026-06-18 09:35:29'),
(856, 13, 'ai', 'Oke, berarti Kak tinggal sendiri! 😊 Dan catatan fasilitas yang Kak minta sudah saya catat — kolam renang, gym, dan hall.\n\nSekarang, ada yang pasti Kak hindari? Misalnya lokasi yang ramai, gedung tua, atau hal lain yang kurang cocok? 🚫', 'whatsapp', '{\"aiProvider\":\"claude\",\"contextSource\":\"flat_json\"}', '2026-06-18 09:35:32', '2026-06-18 09:35:32'),
