(912, 25, 'ai', 'Baik, semua sudah saya catat! 📝 📋 Prioritas Tinggi\n\n✓ Rencana: *Sewa*\n✓ Tipe: *Rumah*\n✓ Lokasi: *Surabaya*\n✓ Masuk: *01 September 2026*\n✓ Keputusan bersama: *Disebutkan di Q4*\n✓ Furnitur: *Semi furnished*\n✓ Fasilitas: *Dapur, Lemari, Kasur*\n✓ Budget: *Rp 9.000.000 - Rp 10.000.000*\n✓ Patokan lokasi: *Dekat pasar dan dekat cafe*\n✓ Preferensi: *Lingkungan sejuk & asri*\n✓ Hindari: *Tidak mau banjir*\n\nSaya akan segera menghubungi Anda dengan rekomendasi properti yang paling sesuai! 🏠\n\nTerima kasih sudah menghubungi saya. 🙏\n\nSalam hangat,\n*LEO FELIX*\n*Elevan Property*', 'whatsapp', '{\"aiProvider\":\"private_agent\",\"contextSource\":\"flat_json\"}', '2026-06-25 03:49:08', '2026-06-25 03:49:08'),
(913, 25, 'customer', 'PORT=5005\nFRONTEND_PORT=5173\n\nAPP_NAME=Elevan Property\n\nDB_HOST=localhost\nDB_USER=root\nDB_PASSWORD=\nDB_NAME=db_property\nDB_DIALECT=mysql\n\nGOOGLE_SHEET_ID=1nwy276VXH0JvDZVOoddBbqmr9jwpydoKrukWY2Jukw4\nGOOGLE_SHEET_GID=0\nGOOGLE_SHEET_TAB_NAME=\nGOOGLE_SERVICE_ACCOUNT_JSON_PATH=./google-service-account.json\n\nOPENAI_API_KEY=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\n# OPENAI_MODEL=gpt-5.4-mini\nOPENAI_MODEL=gpt-4o-mini\nOPENAI_STORE_RESPONSE=true\nOPENAI_MAX_OUTPUT_TOKENS=0\n\nANTHROPIC_API_KEY=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\nCLAUDE_MODEL=claude-haiku-4-5\nCLAUDE_API_VERSION=2023-06-01\nCLAUDE_MAX_TOKENS=100\n\nAI_PRIMARY_PROVIDER=private # chatgpt | claude | private (private = chatbotPrivateController, untuk testing fitur baru sebelum deploy ke public)\n# AI_PRIMARY_TAG — footer \"&gt; Sent via &lt;tag&gt;\" yang ditambahkan ke setiap pesan WA keluar\n# (Fonnte/TimelinesAI/360dialog/ChakraHQ). Kosongkan untuk menonaktifkan footer.\nAI_PRIMARY_TAG=propmatches.netlify.app\n\nENABLE_CLAUDE_FALLBACK=true\nENABLE_CHATBOT_PRIVATE_CONTROLLER=true\n\nFONNTE_TOKEN=m5HDmV4hAYRFBgTdkfDR\nENABLE_AI_WHATSAPP=true\n\n# Fonnte Message Polling (aktif polling ke Fonnte API untuk ambil pesan masuk)\n# Set false untuk matikan polling\nFONNTE_POLLING_ENABLED=true\n# Interval polling dalam milidetik (default: 10000 = 10 detik)\nFONNTE_POLLING_INTERVAL_MS=10000\n\nTIMELINESAI_API_KEY=08d9f985-7866-484c-a2f7-1d1d587bd48a\n\n# ==============================================================\n# FONNTE SEND — Timeout &amp; Retry untuk pengiriman pesan WhatsApp\n# ==============================================================\n# FONNTE_TIMEOUT_MS   : waktu tunggu koneksi per percobaan (ms)\n#                       Default 30000 (30 detik)\n# FONNTE_RETRY_COUNT  : jumlah percobaan ulang jika ETIMEDOUT / ECONNRESET\n#                       Default 3 (total 3 kali, termasuk percobaan pertama)\n# FONNTE_RETRY_DELAY_MS : jeda awal antar percobaan (ms) — meningkat linear\n#                         Percobaan 1→2: 1× delay, 2→3: 2× delay, dst.\n#                         Default 3000 (3 detik, 6 detik, ...)\nFONNTE_TIMEOUT_MS=30000\nFONNTE_RETRY_COUNT=3\nFONNTE_RETRY_DELAY_MS=3000\n\n# ==============================================================\n# MASSEGE_TERMINAL — Platform mana yang tampil di terminal\n# ==============================================================\n# Nilai: FONNTE | TIMELINESAI | CHAKRAHQ (satu atau lebih, pisah koma)\n# FONNTE      = fonnteChatController.js menampilkan chat di terminal\n# CHAKRAHQ    = chakraHQController.js menampilkan chat di terminal\n# TIMELINESAI = timelinesAIChatController.js menampilkan chat di terminal\n#\n# Contoh satu platform  : MASSEGE_TERMINAL=FONNTE\n# Contoh multi platform : MASSEGE_TERMINAL=FONNTE,CHAKRAHQ,TIMELINESAI\nMASSEGE_TERMINAL=TIMELINESAI\n\nCHATBOT_COOKIE_TTL_MINUTES=90\n\nSKILL_MAX_WEBSITE_CHARACTERS=12000\nSKILL_MAX_RESPONSE_CHARACTERS=22000\nSKILL_MAX_PROJECT_CHARACTERS=36000\n\n# Apify - Rumah123 Scraper\nAPIFY_API_TOKEN=apify_api_hd8TzxQYbulU71ol5QfIVMeJsDdXX21md2H0\n\n# ON/OFF toggle untuk live Rumah123 data\n# ON  = Chatbot menggunakan live data dari Rumah123 (via Apify)\n# OFF = Chatbot menggunakan static data dari JSON catalog (frontend/public/json_data)\nRUMAH123_DATA=OFF\n\n# Lokasi yang di-warmup saat server start (pisahkan dengan koma)\nRUMAH123_WARMUP_LOCATIONS=Jakarta Selatan,Surabaya\n\n# ==============================================================\n# AUTHENTICATION SETTINGS (Login &amp; Register Users)\n# ==============================================================\n\n# JWT Secrets — ganti dengan string random sebelum production\nACCESS_TOKEN_SECRET=elevan_access_secret_iuewg928g0wbigw78981091nLJkosniqLwq83egijc\nREFRESH_TOKEN_SECRET=elevan_refresh_secret_837qbdgwosDapoznchvdo07sNckaidskjajwiuq98y8\n\n# Expiry token — sesuai jsonwebtoken expiresIn format (60s, 5m, 2h, 1d)\n# Access token expire setiap 5 menit (frontend auto-refresh ke /refreshTokenController)\nACCESS_TOKEN_EXPIRY=5m\nREFRESH_TOKEN_EXPIRY=1d\n\n# Cookie name untuk menyimpan refresh_token (HttpOnly)\nCOOKIE_REFRESH_TOKEN=Elevan_Refresh_Token\n\n# Bcrypt salt rounds (10-12 recommended)\nBCRYPT_SALT_ROUNDS=10\n\n# ==============================================================\n# HTTP STATUS CODES (untuk konsistensi respon controller)\n# ==============================================================\nHTTP_OK=200\nHTTP_CREATED=201\nHTTP_NO_CONTENT=204\nHTTP_BAD_REQUEST=400\nHTTP_UNAUTHORIZED=401\nHTTP_FORBIDDEN=403\nHTTP_NOT_FOUND=404\nHTTP_CONFLICT=409\nHTTP_INTERNAL_SERVER_ERROR=500\nHTTP_NOT_IMPLEMENTED=501\nHTTP_BAD_GATEWAY=502\nHTTP_SERVICE_UNAVAILABLE=503\n\n# ==============================================================\n# Catalog Chat Settings\n# ==============================================================\nRESPOND_CATALOG_RUN=OFF # ON = Chatbot merespon dengan catalog, OFF = chatbot tidak merespon dengan catalog, namun memberikan summary saja\n\nPAGINATION_ROWS = 4', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"51172990-e034-4b64-b44c-80d66c2c4b55\",\"platform\":\"timelinesai\"}', '2026-06-25 07:33:16', '2026-06-25 07:33:16'),
